import {createProject,demoProject,validateProject,parseImport,summarize,playerKey,toCSV,projectBackup,readBackup,id} from './domain.mjs';
import {StudioStore} from './store.mjs';
import {makeReport,makeVTT,recordPlaylist} from './export.mjs';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const store=new StudioStore();
const state={projects:[],project:null,route:'overview',selected:null,filter:{search:'',result:'all',review:'all',player:'all',tag:'all'},objectURL:null,dirty:false,busy:false,recording:false,navigating:false,abort:null,preview:null,history:[],storage:null,importing:null};
let toastTimer;let acceptedHash=location.hash||'#/overview';let navigationEpoch=0;const statusName={draft:'编辑中',review:'待复核',approved:'已批准'};
const labels={overview:'工作总览',projects:'比赛项目',review:'回合复核',analysis:'数据分析',playlist:'片单制作',reports:'报告与交付',settings:'工作室设置'};
const navIcons={overview:'▦',projects:'▤',review:'▷',analysis:'▥',playlist:'▧',reports:'↗',settings:'⚙'};
const pct=v=>Number.isFinite(v)?`${(v*100).toFixed(1)}%`:'—';
const time=v=>Number.isFinite(v)?`${String(Math.floor(v/60)).padStart(2,'0')}:${(v%60).toFixed(1).padStart(4,'0')}`:'—';
const date=v=>v?new Date(v).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'—';
const bytes=v=>v>1048576?`${(v/1048576).toFixed(1)} MB`:`${Math.round((v||0)/1024)} KB`;
const result=p=>p.made===true?'命中':p.made===false?'未中':'未知';
const badge=p=>`<span class="badge ${esc(p.status)}">${statusName[p.status]||'草稿'}</span>`;
const synthetic=p=>p?.video?.url==='media/demo.mp4';
function toast(text){$('#toast').textContent=text;$('#toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').hidden=true,5000);}
function message(error){if(error?.issues?.length)return error.issues.filter(i=>i.severity==='error').slice(0,4).map(i=>(i.playId?i.playId+'：':'')+issueText(i)).join('；');if(error?.code==='CONFLICT')return '其他页面已保存了更新版本。你的修改尚未覆盖它；请先下载当前草稿，再载入最新项目。';if(error?.name==='QuotaExceededError')return '浏览器存储空间不足。请导出项目备份，或使用完整本机版处理较大视频。';return error?.message||String(error);}
function download(content,name,type='application/json'){const b=content instanceof Blob?content:new Blob([content],{type}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
const filename=p=>(p.name||'CourtLens').replace(/[<>:"/\\|?*\u0000-\u001f]/g,'_').slice(0,90);
const button=(label,action,cls='',extra='')=>`<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;
const field=(label,name,value,type='text',extra='')=>`<label class="field"><span>${label}</span><input name="${esc(name)}" type="${esc(type)}" value="${esc(value)}" ${extra}></label>`;
const options=(rows,current)=>rows.map(([v,t])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${esc(t)}</option>`).join('');
const projectLink=(route,p=state.project)=>`#/${route}/${p.id}`;
const summaryCard=(label,value,note,red=false)=>`<div class="stat ${red?'red':''}"><div class="stat-label">${label}</div><div class="stat-value">${esc(value)}</div><div class="stat-note">${esc(note)}</div></div>`;
function tabs(p){return `<div class="project-tabs">${['review','analysis','playlist','reports'].map(r=>`<a href="${projectLink(r,p)}" class="${state.route===r?'active':''}">${labels[r]}</a>`).join('')}<button class="text-button small" data-action="history">版本历史 · r${p.revision}</button></div>`;}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><span class="eyebrow">${state.route==='overview'?'YOUR WORKSPACE':'COURTLENS / '+labels[state.route]}</span><h1>${esc(title)}</h1><p>${esc(sub)}</p></div><div class="actions">${actions}</div></div>`;}
function empty(title,text,actions=''){return `<div class="empty"><h2>${title}</h2><p>${text}</p><div class="actions">${actions}</div></div>`;}
function issueText(i){const map={EVIDENCE_ARCHIVED:'高级证据已留档：保留原回合、Gravity、Leverage、轨迹、标注及指标语义，可在回合复核页查看，项目 JSON 备份会保留。当前统计和 WebM 不计算或绘制这些字段；完整比赛上下文请另存原 JSON，使用原证据工作台。',SOURCE_EVIDENCE:'原始证据必须包含有效的记录与指标语义。',PROJECT_SIZE:'项目数据超过 32 MB，请拆分为较小项目。',PLAY_TIME:'时间必须是有效的非负视频秒数。',PLAY_RANGE:'回合结束时刻必须晚于开始时刻。',VIDEO_BOUNDS:'回合结束时刻超出了视频时长。',SHOT_TIME:'出手时刻必须在回合开始与结束之间。',RESULT_TIME:'结果时刻必须不早于出手，且在回合范围内。',XFG:'xFG 必须留空或填写 0–1 的概率。',COORDINATE_PAIR:'投篮 x、y 坐标必须同时填写或同时留空。',COORDINATE:'投篮坐标必须在 0–1 之间。',DUPLICATE_PLAY_ID:'回合 ID 重复，请修改后再导入。',PLAY_SOURCE:'尚未填写该回合的来源。',CLIP_BOUNDS:'片段入出点必须在原回合范围内，且出点晚于入点。',CLIP_PLAY:'片段引用的回合不存在。',POINTS:'投篮分值仅接受 2 或 3。',VIDEO_REQUIRED:'尚未绑定视频，导入后才能批准成片。',SOURCE_REQUIRED:'请填写项目来源说明。',PLAYS_REQUIRED:'尚无回合，添加或导入回合表开始复核。',REVIEW_REQUIRED:'仍有未复核回合，请逐条核对。',VIDEO_REATTACH_REQUIRED:'备份不包含视频，请重新绑定原视频。',UNKNOWN_RESULT:'结果未知：不计作未中，也不进入命中率分母。',MISSING_SOURCE:'回合缺少来源说明。',MISSING_XFG:'没有提供 xFG，该回合不计入期望得分。',ASSUMED_TIMING:'缺少出手或结果时刻，已暂用回合结束时刻；请回看校正。'};return map[i.code]||i.message;}
function issuesHTML(p,limit=6){const list=validateProject(p);return list.length?`<ul class="issues">${list.slice(0,limit).map(i=>`<li class="${i.severity}">${i.severity==='error'?'●':'○'} ${i.playId?esc(i.playId)+' · ':''}${esc(issueText(i))}</li>`).join('')}</ul>${list.length>limit?`<p class="micro muted">另有 ${list.length-limit} 条提示，完整信息见数据检查。</p>`:''}`:'<p class="micro">✓ 数据结构与时间范围检查通过。来源真实性仍需人工确认。</p>';}
function refreshShell(){const p=state.project;$('#page-label').textContent=labels[state.route]||'工作总览';$('#navigation').innerHTML=Object.entries(labels).map(([r,t])=>`<a href="#/${r}${!['overview','projects','settings'].includes(r)&&p?'/'+p.id:''}" class="${state.route===r?'active':''}" ${state.route===r?'aria-current="page"':''} title="${t}"><span class="nav-icon" aria-hidden="true">${navIcons[r]}</span><span>${t}</span></a>`).join('');$('#active-project').innerHTML='<option value="">选择比赛项目</option>'+state.projects.filter(p=>!p.archived).map(p=>`<option value="${esc(p.id)}" ${state.project?.id===p.id?'selected':''}>${esc(p.name)}</option>`).join('');}
async function loadProjects(){state.projects=await store.list();}
async function navigate(){window.scrollTo({top:0,behavior:'instant'});const epoch=++navigationEpoch;state.navigating=true;$('#main').inert=true;if(state.recording){toast('正在录制，请完成或取消后切换页面。');return;}const [route,projectId]=(location.hash.slice(2)||'overview').split('/');state.route=Object.hasOwn(labels,route)?route:'overview';let active=projectId;try{active ||=localStorage.getItem('courtlens-active-project');}catch{}if(active){const loaded=await store.get(active);if(epoch!==navigationEpoch)return;state.project=loaded;}if(!state.project&&!projectId)state.project=state.projects.find(p=>!p.archived)||null;if(projectId&&!state.project){$('#main').innerHTML=empty('项目不存在','项目可能来自另一台设备或已清理的浏览器存储。',button('返回项目库','projects','primary'));state.navigating=false;$('#main').inert=false;refreshShell();return;}if(state.project){try{localStorage.setItem('courtlens-active-project',state.project.id);}catch{}}acceptedHash=location.hash||'#/overview';state.dirty=false;state.history=[];state.filter={search:'',result:'all',review:'all',player:'all',tag:'all'};await render();if(epoch===navigationEpoch){state.navigating=false;$('#main').inert=false;}}
function goto(route,p=state.project){if(state.dirty){toast('请先保存表单修改，再切换页面。');return;}const next=`#/${route}${p&&!['overview','projects','settings'].includes(route)?'/'+p.id:''}`;if(location.hash===next)navigate().catch(fail);else{window.history.pushState(null,'',next);navigate().catch(fail);}}
function cleanupMedia(){const video=$('#review-video');if(video)video.pause();if(state.objectURL){URL.revokeObjectURL(state.objectURL);state.objectURL=null;}state.preview=null;}
async function render(){cleanupMedia();refreshShell();const main=$('#main');if(!['overview','projects','settings'].includes(state.route)&&!state.project){main.innerHTML=empty('先创建一个比赛项目','导入自己的比赛视频和回合表，然后完成复核、片单制作与交付。',button('新建项目','new','primary')+button('载入合成演练','demo'));return;}const views={overview:overview,projects:projectsView,review:reviewView,analysis:analysisView,playlist:playlistView,reports:reportsView,settings:settingsView};main.innerHTML=views[state.route]();setBusy(state.busy);document.title=`${labels[state.route]} · CourtLens Studio`;if($('#review-video'))await bindVideo();if(state.route==='settings')await storageStatus();}
function overview(){const ps=state.projects.filter(p=>!p.archived),plays=ps.flatMap(p=>p.plays),pending=plays.filter(p=>!p.reviewed).length;return heading('让复盘，成为下一步行动。','从比赛素材到教练报告与内容片单，在一个工作室里完成。',button('导入项目备份','import-backup')+button('新建项目','new','primary'))+`<div class="stats">${summaryCard('比赛项目',ps.length,'持续保存 · 可恢复历史版本')}${summaryCard('待复核回合',pending,`${plays.length} 条回合 / ${plays.filter(p=>p.reviewed).length} 条已复核`,true)}${summaryCard('已选片段',ps.reduce((n,p)=>n+p.playlist.length,0),'按项目管理 · 支持裁切与排序')}${summaryCard('已批准项目',ps.filter(p=>p.status==='approved').length,'来源、视频和回合均完成复核')}</div><div class="panel welcome"><div><span class="eyebrow">FROM FOOTAGE TO A DECISION</span><h2>两种工作方式，同一条证据链</h2><p>教练：逐回合复核、球员比较、输出赛后报告。编辑：从回合库筛片、调整入出点、生成可播放的片单成片。</p><div class="actions">${button('开始教练复盘','new-coach')}${button('开始内容制作','new-editor')}</div></div><svg class="court-emblem" viewBox="0 0 160 140" aria-hidden="true"><g stroke="#b8cae4" fill="none" stroke-width="1.5"><rect x="8" y="8" width="144" height="124"/><path d="M57 8v51h46V8M19 8v25a62 62 0 0 0 122 0V8M64 24h32"/><circle cx="80" cy="59" r="19"/><circle cx="80" cy="29" r="4"/></g></svg></div><div class="columns"><div class="stack"><section class="panel"><div class="panel-header"><div><h2>继续你的工作</h2><p>最近更新的项目与下一步动作</p></div><a class="inline-link" href="#/projects">全部项目 →</a></div>${ps.length?`<div class="table-wrap"><table><thead><tr><th>比赛 / 项目</th><th>复核进度</th><th>状态</th><th></th></tr></thead><tbody>${ps.slice(0,5).map(p=>`<tr><td><b>${esc(p.name)}</b><small>${synthetic(p)?'合成演练 · 非真实 NBA 事件':esc(p.opponent||'用户导入素材')} · r${p.revision}</small></td><td>${p.plays.filter(v=>v.reviewed).length} / ${p.plays.length}<small>${date(p.updatedAt)}</small></td><td>${badge(p)}</td><td><a href="${projectLink('review',p)}">继续复盘 →</a></td></tr>`).join('')}</tbody></table></div>`:empty('工作室准备好了','创建自己的比赛项目，或用合成素材走通完整流程。',button('载入合成演练','demo','primary'))}</section><section class="panel"><div class="panel-header"><div><h2>待办队列</h2><p>根据真实项目状态生成，没有虚构任务</p></div><span class="badge">${pending} 条待复核</span></div>${ps.flatMap(p=>p.plays.filter(v=>!v.reviewed).slice(0,3).map(v=>({p,v}))).slice(0,5).map(({p,v})=>`<div class="list-row"><div><strong>${esc(v.shooter)} · ${esc(v.tag||'未分类回合')}</strong><p>${esc(p.name)} / ${time(v.start)}—${time(v.end)}</p></div><a class="inline-link" href="${projectLink('review',p)}" data-play="${esc(v.id)}">去复核 →</a></div>`).join('')||'<p class="micro muted">当前没有待复核回合。可以开始编排片单或创建新项目。</p>'}</section></div><div class="stack"><section class="panel"><div class="panel-header"><div><h2>一场比赛的工作流</h2><p>每一步都连接到实际功能</p></div></div><div class="workflow">${[['01','建立素材项目','导入视频和 CSV / JSON，记录来源。'],['02','逐回合复核','校正时间、结果、标签和复盘笔记。'],['03','分析与选片','筛选球员、比较效率、编排片段。'],['04','批准并交付','下载报告、数据、字幕与无声成片。']].map(([n,t,d])=>`<div class="workflow-step"><span class="step-number">${n}</span><div><h3>${t}</h3><p>${d}</p></div></div>`).join('')}</div></section><section class="panel"><h2>数据始终在你手上</h2><p class="micro">项目和原视频保存在当前浏览器。相同网址、相同浏览器可继续工作；切换设备或清理站点数据前，请备份项目并保留原视频。</p><a class="inline-link" href="#/settings">查看存储与数据说明 →</a></section></div></div>`;}
function projectsView(){const ps=state.projects.filter(p=>(state.filter.review==='archived'?p.archived:!p.archived)&&p.name.toLowerCase().includes(state.filter.search.toLowerCase()));return heading('比赛项目','把素材、分析、片单和修订历史保存在同一个项目中。',button('导入备份','import-backup')+button('新建项目','new','primary'))+`<div class="filters"><input id="project-search" type="search" placeholder="搜索项目名称" aria-label="搜索项目名称" value="${esc(state.filter.search)}"><select id="project-status" aria-label="项目范围">${options([['active','工作中的项目'],['archived','已归档项目']],state.filter.review==='archived'?'archived':'active')}</select><span class="push micro muted">${ps.length} 个项目</span>${button('载入合成演练','demo','small')}</div>${ps.length?`<div class="project-grid">${ps.map(p=>`<article class="panel project-card ${p.archived?'archived':''}"><div class="project-cover"><b>${p.scenario==='coach'?'REVIEW':'STUDIO'}</b><span>${esc(p.date||'未设置比赛日期')}<br>${p.video?time(p.video.duration)+' 视频':'待导入视频'}</span></div><div class="project-meta">${badge(p)}${synthetic(p)?'<span class="badge synthetic">合成演练</span>':`<span>${esc(p.opponent||'自有比赛')}</span>`}</div><div><h3>${esc(p.name)}</h3><p>${p.plays.length} 条回合 · ${p.plays.filter(v=>v.reviewed).length} 条已复核 · ${p.playlist.length} 段片单</p></div><div class="project-meta"><span>r${p.revision} · ${date(p.updatedAt)}</span><a href="${projectLink('review',p)}">打开项目 →</a></div></article>`).join('')}</div>`:empty('这里还没有项目','从自己的视频开始，也可以导入之前下载的项目备份。',button('新建项目','new','primary'))}`;}
function projectHeading(p,sub,actions=''){return heading(p.name,`${synthetic(p)?'合成演练 · ':''}${sub}`,`${badge(p)}${actions}`)+tabs(p);}
function videoHTML(p){return `<div class="video-box"><video id="review-video" controls playsinline preload="metadata" aria-label="项目视频"></video><div class="video-empty" id="video-empty" ${p.video&&!p.video.needsReattach?'hidden':''}><strong>${p.video?.needsReattach?'重新绑定原视频':'导入你的比赛视频'}</strong><p>视频保存在当前浏览器，不会上传。<br>支持浏览器可解码格式，单文件最多 512 MB。</p>${button('选择视频文件','attach-video','primary')}</div><div class="video-overlay" id="video-caption" hidden></div></div><div class="video-tools"><span class="time-display" id="video-time">00:00.0 / ${time(p.video?.duration)}</span><div class="actions">${button('↶ 3 秒','back','small')}${button('前进 3 秒 ↷','forward','small')}${button(p.video?'更换视频':'导入视频','attach-video','small')}</div></div>`;}
function filteredPlays(p){return p.plays.filter(v=>(state.filter.review!=='pending'||!v.reviewed)&&(state.filter.review!=='done'||v.reviewed)&&(state.filter.result==='all'||(state.filter.result==='made'?v.made===true:state.filter.result==='missed'?v.made===false:v.made===null))&&(state.filter.player==='all'||playerKey(v)===state.filter.player)&&(state.filter.tag==='all'||v.tag===state.filter.tag));}
function selectedPlay(){return state.project?.plays.find(p=>p.id===state.selected)||state.project?.plays[0];}
function sourceEvidenceHTML(play){if(!play?.sourceEvidence)return '';const evidence=play.sourceEvidence,row=evidence.record,metrics=row.metrics||{};return `<section class="panel source-evidence"><h3>原始回合证据</h3><p class="micro muted">导入时的原记录 · 保留来源单位与语义，未经独立认证。修改复盘字段不会改写原始证据。以下高级指标不参与 Studio 统计或 WebM 叠加。</p><div class="source-metrics">${Object.entries(metrics).map(([key,value])=>`<div><small>${esc(key)}</small><b>${esc(typeof value==='object'?JSON.stringify(value):String(value))}</b></div>`).join('')||'<p class="micro">原记录未提供高级指标。</p>'}</div><p class="micro">${Array.isArray(row.tracks)?row.tracks.length:0} 条轨迹记录 · ${Array.isArray(row.annotations)?row.annotations.length:0} 条标注 · 原始内容随项目 JSON 备份保留</p><details><summary>展开原始记录与指标语义</summary><pre>${esc(JSON.stringify(evidence,null,2))}</pre></details><p class="micro muted">完整数据集的比赛、球员及其他顶层元数据请从原 JSON 查阅。CSV 和 HTML 报告只输出当前复盘字段。</p></section>`;}
function reviewView(){const p=state.project,ps=filteredPlays(p);if(!state.selected||!p.plays.some(v=>v.id===state.selected))state.selected=p.plays[0]?.id;const v=selectedPlay();return projectHeading(p,`逐回合核对时间、结果与来源 · 当前版本 r${p.revision}`,button('项目资料','project-info','small')+button('导入回合表','import-data','primary'))+`<div class="review-layout"><div><section>${videoHTML(p)}</section>${v?playForm(v)+sourceEvidenceHTML(v):empty('还没有回合','播放视频定位一个回合，再添加记录；也可以导入已有的回合表。',button('添加第一个回合','add-play','primary'))}</div><div class="stack"><section class="panel"><div class="panel-header"><div><h2>回合队列 <span class="muted">${p.plays.length}</span></h2><p>${p.plays.filter(v=>v.reviewed).length} 条已复核 / 点击回合定位视频</p></div>${button('＋ 添加','add-play','small')}</div><div class="filters"><select id="review-filter" aria-label="复核状态">${options([['all','全部回合'],['pending','待复核'],['done','已复核']],state.filter.review)}</select></div><div class="clip-queue">${ps.map((v,i)=>`<button class="queue-item ${state.selected===v.id?'active':''}" data-action="select-play" data-id="${esc(v.id)}"><span class="queue-number">${String(p.plays.indexOf(v)+1).padStart(2,'0')}</span><span class="queue-main"><strong>${esc(v.shooter)} · ${esc(v.tag||'未分类')}</strong><small>${time(v.start)}—${time(v.end)} · ${v.points} 分 / ${result(v)}</small></span><span class="queue-dot ${v.reviewed?'reviewed':''}" aria-label="${v.reviewed?'已复核':'未复核'}">${v.reviewed?'✓':'○'}</span></button>`).join('')||'<p class="micro muted">当前筛选没有回合。</p>'}</div></section><section class="panel"><div class="panel-header"><h2>数据检查</h2>${button('查看全部','quality','text-button small')}</div>${issuesHTML(p)}<div class="section-space info">复核是对当前输入的人工确认。未知结果可以保留为未知，不会被统计为投失。</div></section><section class="panel"><h3>来源记录</h3><p class="micro break">${esc(p.source||'尚未填写。请在项目资料中记录视频和数据来源。')}</p><div class="micro muted">${p.video?esc(p.video.name)+' · '+(synthetic(p)?'内置合成素材':bytes(p.video.size)):'视频尚未绑定'}</div></section></div></div>`;}
function playForm(v){return `<section class="panel"><div class="panel-header"><div><h2>${esc(v.shooter)} · 回合详情</h2><p>${esc(v.id)} · ${v.reviewed?'已复核；修改内容后需重新确认':'请对照视频逐项核对'}</p></div><span class="badge ${v.reviewed?'approved':'draft'}">${v.reviewed?'已复核':'待复核'}</span></div><form id="play-form"><input type="hidden" name="id" value="${esc(v.id)}"><div class="form-grid">${field('开始 / 秒','start',v.start,'number','step="any" min="0" required')}${field('结束 / 秒','end',v.end,'number','step="any" min="0" required')}${field('出手时刻 / 秒','shotTime',v.shotTime,'number','step="any" min="0" required')}${field('结果时刻 / 秒','resultTime',v.resultTime,'number','step="any" min="0" required')}${field('投篮球员','shooter',v.shooter,'text','required maxlength="100"')}${field('球队','team',v.team,'text','maxlength="100"')}<label class="field"><span>出手分值</span><select name="points">${options([[2,'两分投篮'],[3,'三分投篮']],v.points)}</select></label><label class="field"><span>结果</span><select name="made">${options([['unknown','未知 / 尚未核对'],['made','命中'],['missed','未中']],v.made===null?'unknown':v.made?'made':'missed')}</select></label>${field('战术 / 自定义标签','tag',v.tag,'text','list="tag-options" maxlength="100"')}${field('来源提供的 xFG（0–1，可空）','xfg',v.xfg??'','number','step="any" min="0" max="1"')}${field('半场 x（0–1，可空）','x',v.x??'','number','step="any" min="0" max="1"')}${field('半场 y（0–1，可空）','y',v.y??'','number','step="any" min="0" max="1"')}<label class="field full"><span>回合来源</span><input name="source" value="${esc(v.source)}" maxlength="2000" placeholder="如：自摄训练视频 2026-09-22，人工逐帧记录"></label><label class="field full"><span>复盘笔记 / 待验证假设</span><textarea name="notes" maxlength="5000" placeholder="记录观察、需要核对的问题和下一步训练建议。">${esc(v.notes)}</textarea></label></div><datalist id="tag-options"><option>挡拆</option><option>定点投篮</option><option>快攻</option><option>篮下终结</option><option>防守轮转</option><option>二次进攻</option></datalist><div class="micro muted section-space">坐标为人工填写或导入的半场归一化位置；系统不会从视频自动检测。xFG 缺失时留空。</div><div class="form-actions">${button('删除回合','delete-play','text-button danger','type="button"')}${button('加入片单','add-clip','secondary','type="button"')}<button type="submit">保存修改</button>${button(v.reviewed?'取消复核':'确认本条已复核','review-play','primary','type="button"')}</div></form></section>`;}
function filtersHTML(p){const players=[...new Map(p.plays.map(v=>[playerKey(v),`${v.shooter} · ${v.team||'未填球队'}`])).entries()],tags=[...new Set(p.plays.map(v=>v.tag).filter(Boolean))];return `<div class="filters"><select id="player-filter" aria-label="筛选球员">${options([['all','全部球员'],...players],state.filter.player)}</select><select id="tag-filter" aria-label="筛选战术标签">${options([['all','全部战术标签'],...tags.map(v=>[v,v])],state.filter.tag)}</select><select id="result-filter" aria-label="筛选投篮结果">${options([['all','全部结果'],['made','命中'],['missed','未中'],['unknown','未知']],state.filter.result)}</select><span class="push micro muted">当前筛选 ${filteredPlays(p).length} / ${p.plays.length} 条回合</span></div>`;}
function courtHTML(plays){const located=plays.filter(v=>v.x!==null&&v.y!==null);return `<div class="court"><svg viewBox="0 0 500 440" role="img" aria-label="人工或导入坐标的半场投篮分布"><rect x="12" y="12" width="476" height="412" rx="2" fill="#f6f8fc" stroke="#c3cede"/><g stroke="#c3cede" stroke-width="1.5" fill="none"><path d="M176 12v168h148V12M38 12v125a226 226 0 0 0 424 0V12M221 50h58"/><circle cx="250" cy="180" r="54"/><circle cx="250" cy="63" r="7"/><path d="M195 424a55 55 0 0 1 110 0"/></g>${located.map(v=>v.made===false?`<g stroke="#c9082a" stroke-width="3"><title>${esc(v.shooter)} · 未中</title><path d="M${12+v.x*476-5} ${12+v.y*412-5}l10 10m-10 0l10-10"/></g>`:`<circle cx="${12+v.x*476}" cy="${12+v.y*412}" r="6" fill="${v.made===true?'#17408b':'white'}" stroke="#17408b" stroke-width="2"><title>${esc(v.shooter)} · ${result(v)}</title></circle>`).join('')}${!located.length?'<text x="250" y="287" text-anchor="middle" fill="#7d8fa8" font-size="13">没有坐标数据，不生成虚构热区</text>':''}</svg></div><div class="court-legend"><span><i class="court-key"></i>命中</span><span><i class="court-key miss"></i>× 未中</span><span>○ 未知</span></div><p class="micro muted section-space">${located.length} / ${plays.length} 条回合有坐标。球场为示意；x 从左到右，y 从上到下，范围均为 0–1。</p>`;}
function analysisView(){const p=state.project,ps=filteredPlays(p),s=summarize(ps),xshots=ps.filter(v=>v.xfg!==null),knownExpected=xshots.filter(v=>v.made!==null);return projectHeading(p,'比较球员与战术表现，所有指标随筛选重新计算。',button('下载筛选数据','filtered-csv','small'))+filtersHTML(p)+`<div class="stats">${summaryCard('投篮命中率 FG%',pct(s.fgPct),`${s.made} 命中 / ${s.attempts} 次已知结果出手`)}${summaryCard('有效命中率 eFG%',pct(s.efgPct),'三分命中按 1.5 次命中计权')}${summaryCard('已记录投篮得分',s.points,'仅命中的两分 / 三分，不含罚球')}${summaryCard('未知结果',ps.length-s.attempts,'不计入命中率分母',true)}</div><div class="columns equal"><section class="panel"><div class="panel-header"><div><h2>投篮位置分布</h2><p>只绘制实际提供的坐标</p></div><span class="task-tag">SHOT MAP</span></div>${courtHTML(ps)}</section><div class="stack"><section class="panel"><div class="panel-header"><div><h2>球员投篮效率</h2><p>展示命中率与样本量，小样本不代表稳定能力</p></div></div>${s.players.map(v=>`<div class="bar-row"><span>${esc(v.name)}${v.team?` · ${esc(v.team)}`:''}</span><div class="bar-track"><div class="bar-fill" style="width:${(v.fgPct||0)*100}%"></div></div><b>${pct(v.fgPct)}</b></div><div class="micro muted" style="margin-top:-9px;margin-left:108px">${v.made} / ${v.attempts} 次 · ${v.points} 分</div>`).join('')||'<p class="micro muted">导入回合数据后可比较球员。</p>'}</section><section class="panel"><div class="panel-header"><div><h2>战术标签分布</h2><p>来自人工标注与导入，没有自动战术识别</p></div></div>${s.tags.map(v=>`<div class="bar-row"><span>${esc(v.name||'未分类')}</span><div class="bar-track"><div class="bar-fill" style="width:${ps.length?v.count/ps.length*100:0}%;background:#7191c4"></div></div><b>${v.count} 条</b></div>`).join('')||'<p class="micro muted">尚未标注战术标签。</p>'}</section></div></div><section class="panel section-space"><div class="panel-header"><div><h2>预期与结果：同一批样本再比较</h2><p>xFG 来自输入，系统不将其当作自己训练的预测模型。</p></div><span class="badge">覆盖 ${xshots.length} / ${ps.length}</span></div><div class="columns equal"><div><div class="stat-value">${s.expectedPoints===null?'—':s.expectedPoints.toFixed(2)} <small style="font-size:13px;color:#718198">输入期望得分</small></div><p class="micro">Σ（xFG × 投篮分值），只覆盖有 xFG 的 ${xshots.length} 条回合。</p></div><div><h3>可比较子集：${knownExpected.length} 条</h3><p class="micro">同时有 xFG 与结果的回合，实际得分 ${knownExpected.reduce((n,v)=>n+(v.made?v.points:0),0)}，输入期望得分 ${knownExpected.reduce((n,v)=>n+v.xfg*v.points,0).toFixed(2)}。单场差值是描述性结果，不能证明因果关系或球员真实能力。</p></div></div></section><section class="panel section-space"><div class="panel-header"><h2>数据明细与证据入口</h2>${button('将筛选结果加入片单','add-filtered','small')}</div>${playsTable(ps)}</section>`;}
function playsTable(ps){return `<div class="table-wrap"><table><thead><tr><th>球员 / 来源</th><th>时间</th><th>标签</th><th>结果</th><th class="numeric">xFG</th><th>复核</th><th></th></tr></thead><tbody>${ps.map(v=>`<tr><td><b>${esc(v.shooter)}</b><small title="${esc(v.source)}">${esc(v.team)} · ${esc(v.id)}</small></td><td>${time(v.start)}—${time(v.end)}</td><td>${esc(v.tag||'未分类')}</td><td>${v.points} 分 · ${result(v)}</td><td class="numeric">${pct(v.xfg)}</td><td>${v.reviewed?'✓ 已复核':'○ 待复核'}</td><td>${button('回看','review-id','text-button small',`data-id="${esc(v.id)}"`)}</td></tr>`).join('')||'<tr><td colspan="7">当前筛选没有数据。</td></tr>'}</tbody></table></div>`;}
function playlistView(){const p=state.project,total=p.playlist.reduce((n,c)=>n+c.out-c.in,0);return projectHeading(p,'挑选、裁切并排列片段；保存后形成可追溯的制作版本。',button('添加全部回合','add-all','small')+button('前往交付','reports','primary'))+`<div class="review-layout"><div><section class="panel"><div class="panel-header"><div><h2>故事片单</h2><p>${p.playlist.length} 个片段 · 总时长 ${time(total)} · 播放顺序从上到下</p></div>${button('预览片单','preview-playlist','small',p.playlist.length?'':'disabled')}</div>${p.playlist.length?`<div class="timeline" aria-label="片单时间组成">${p.playlist.map((c,i)=>`<div class="timeline-block" style="flex:${c.out-c.in}" title="${esc(c.title)} · ${time(c.out-c.in)}">${i+1} · ${time(c.out-c.in)}</div>`).join('')}</div><form id="playlist-form">${p.playlist.map((c,i)=>{const v=p.plays.find(v=>v.id===c.playId);return `<div class="playlist-item"><span class="item-number">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(v.shooter)} · 原回合 ${time(v.start)}—${time(v.end)}</h3><label class="field"><span>片段标题（报告中显示）</span><input name="title-${esc(c.id)}" value="${esc(c.title)}" maxlength="200"></label><div class="form-grid section-space">${field('入点 / 秒','in-'+c.id,c.in,'number',`step="any" min="${v.start}" max="${v.end}" required`)}${field('出点 / 秒','out-'+c.id,c.out,'number',`step="any" min="${v.start}" max="${v.end}" required`)}</div></div><div class="actions">${button('↑','clip-up','small',`type="button" data-id="${esc(c.id)}" aria-label="上移片段 ${i+1}" ${i===0?'disabled':''}`)}${button('↓','clip-down','small',`type="button" data-id="${esc(c.id)}" aria-label="下移片段 ${i+1}" ${i===p.playlist.length-1?'disabled':''}`)}${button('移除','clip-remove','text-button small danger',`type="button" data-id="${esc(c.id)}"`)}</div></div>`}).join('')}<div class="form-actions"><button type="submit" class="primary">保存片单修改</button></div></form>`:empty('片单还是空的','从右侧回合库添加片段，或把筛选后的分析结果加入片单。',button('添加全部回合','add-all','primary'))}</section></div><div class="stack"><section>${videoHTML(p)}</section><section class="panel"><div class="panel-header"><h2>可用回合</h2><span class="badge">${p.plays.length}</span></div>${p.plays.map(v=>`<div class="list-row"><div><strong>${esc(v.shooter)} · ${result(v)}</strong><p>${time(v.start)}—${time(v.end)} · ${v.reviewed?'已复核':'待复核'}</p></div>${button('＋','clip-id','small',`data-id="${esc(v.id)}" aria-label="添加 ${esc(v.shooter)} 回合到片单"`)}</div>`).join('')||'<p class="micro muted">先到回合复核页创建记录。</p>'}</section><div class="info">片段可重复使用，项目统计不会重复计数。裁切只调整输出范围，不改动原视频。视频成片最多 180 秒，适合教练短片与社交内容初剪。</div></div></div>`;}
function reportsView(){const p=state.project,s=summarize(p.plays),clips=p.playlist.length||p.plays.length,duration=(p.playlist.length?p.playlist:p.plays.map(v=>({in:v.start,out:v.end}))).reduce((n,v)=>n+v.out-v.in,0);return projectHeading(p,'报告、可编辑数据与视频输出，都绑定当前保存版本。',button('下载项目备份','backup','small'))+`<div class="stats">${summaryCard('交付版本','r'+p.revision,date(p.updatedAt))}${summaryCard('已复核',s.reviewed+' / '+p.plays.length,'修改回合内容后需重新复核')}${summaryCard('输出片段',clips,p.playlist.length?'使用已保存片单顺序':'未建片单时使用全部回合')}${summaryCard('输出总时长',time(duration),duration>180?'超过浏览器 180 秒录制上限':'浏览器实时录制 · 无声',duration>180)}</div><div class="columns"><section class="panel"><div class="panel-header"><div><h2>交付中心</h2><p>从这里下载真正的工作成果</p></div>${badge(p)}</div><div class="export-option"><div class="export-icon">HTML</div><div><h3>教练复盘报告</h3><p>球员统计、投篮分布、片段清单、笔记与来源；可在浏览器打印为 PDF。</p></div>${button('下载报告','report','small')}</div><div class="export-option"><div class="export-icon">CSV</div><div><h3>结构化回合表</h3><p>继续在表格工具中分析，或重新导入 CourtLens。</p></div>${button('下载数据','csv','small')}</div><div class="export-option"><div class="export-icon">VTT</div><div><h3>片单同步字幕</h3><p>使用拼接后的输出时间；结果字幕在结果时刻后出现。</p></div>${button('下载字幕','vtt','small',clips?'':'disabled')}</div><div class="export-option"><div class="export-icon">VIDEO</div><div><h3>浏览器成片</h3><p>按片单录制真实视频，叠加球员和时间字幕；输出无声 WebM，最长 180 秒。</p></div>${button('录制并下载','record','primary small',p.status==='approved'&&duration<=180&&clips?'':'disabled')}</div>${p.status!=='approved'?'<p class="disabled-note section-space">视频导出前需逐条复核并批准当前项目。报告与数据允许以明确的草稿状态导出。</p>':''}<section id="record-progress" hidden class="section-space"><h3 id="record-stage">正在准备录制…</h3><div class="progress"><div id="record-bar" style="width:0"></div></div><div class="actions">${button('取消录制','cancel-record','small')}<span class="micro muted">请保持页面可见，录制按视频实际时长进行。</span></div></section><div class="section-space" id="record-player">${videoHTML(p)}</div></section><div class="stack"><section class="panel"><div class="panel-header"><div><h2>批准检查</h2><p>批准后才能输出视频</p></div></div><div class="workflow">${[['1','来源说明',!!p.source],['2','已绑定视频',!!p.video&&!p.video.needsReattach],['3','逐条复核完成',p.plays.length>0&&s.reviewed===p.plays.length],['4','数据结构与时间检查',!validateProject(p).some(v=>v.severity==='error')]].map(([n,t,ok])=>`<div class="workflow-step"><span class="step-number">${ok?'✓':n}</span><div><h3>${t}</h3><p>${ok?'已完成':'尚未完成'}</p></div></div>`).join('')}</div><div class="section-space">${button(p.status==='approved'?'当前版本已批准':'批准当前项目','approve','primary',p.status==='approved'?'disabled':'')}</div></section><section class="panel"><h2>制作记录</h2>${[...(p.activity||[])].reverse().slice(0,7).map(a=>`<div class="list-row"><div class="activity"><span class="activity-dot"></span><div><strong>${esc(a.message||a.action||a.type||'保存项目')}</strong><small>${date(a.at)}</small></div></div></div>`).join('')||'<p class="micro muted">完成保存与交付后，会在这里留下记录。</p>'}</section><div class="info">数据与视频保存在本机浏览器，备份 JSON 不包含原视频。长期保存请同时保留原视频和项目备份；清理站点数据会删除本机工作内容。</div></div></div>`;}
function settingsView(){return heading('你的工作室，你的数据。','查看存储状态、导入规范与系统能力边界。')+`<div class="columns equal"><section class="panel"><div class="panel-header"><div><h2>浏览器存储</h2><p>当前域名和浏览器配置独立保存</p></div><span class="badge">IndexedDB</span></div><div id="storage-status"><p>正在读取…</p></div>${button('申请持久存储','persist','small')}<p class="micro section-space">浏览器可能拒绝持久存储请求。它不能替代备份；无痕模式、清理网站数据或卸载浏览器可能删除本机项目。</p><div class="actions">${button('导入项目备份','import-backup')}${button('下载回合表模板','template')}</div></section><section class="panel"><h2>运行方式</h2><div class="method-row"><span>当前网页版</span><p>单用户、本机数据工作室。支持视频保存、回合编辑、复核、分析、片单、版本恢复及实时无声 WebM 录制。</p></div><div class="method-row"><span>完整本机版</span><p>Python + SQLite + FFmpeg，适合较大素材、后台 MP4 导出、人工画面标注与可选系统配音。</p></div><div class="method-row"><span>当前未提供</span><p>账号、多人权限、云端视频存储、跨设备自动同步、从任意视频自动识别球员与战术。</p></div><a class="inline-link" href="https://github.com/dingyucanada/courtlens/releases/latest" target="_blank" rel="noopener">下载完整本机产品 →</a></section><section class="panel"><h2>数据字段与统计口径</h2><div class="method-row"><span>回合时间</span><p>start / end 是原视频秒数；shotTime / resultTime 在回合内，且结果时刻不能早于出手。</p></div><div class="method-row"><span>FG% / eFG%</span><p>FG% = 命中 ÷ 已知结果出手。eFG% =（命中 + 0.5 × 三分命中）÷ 已知结果出手。未知不算投失。</p></div><div class="method-row"><span>xFG</span><p>输入的 0–1 预测命中概率。缺失不补零，期望得分仅统计有 xFG 的回合子集。</p></div><div class="method-row"><span>投篮坐标</span><p>x、y 均为 0–1，左上角为原点；两项应同时提供。位置来自导入或人工输入。</p></div></section><section class="panel"><h2>从自己的比赛开始</h2><div class="workflow">${[['01','创建项目并记录素材来源'],['02','绑定浏览器可播放的视频'],['03','导入 CSV / JSON，或手工添加回合'],['04','逐条复核后制作片单、批准并导出']].map(([n,t])=>`<div class="workflow-step"><span class="step-number">${n}</span><div><h3>${t}</h3></div></div>`).join('')}</div><div class="info section-space">合成演练用于检验工作流，不能当作真实 NBA 战绩、模型准确率或效果实验。</div></section></div>`;}
async function storageStatus(){try{const s=await store.storageInfo();state.storage=s;$('#storage-status').innerHTML=`<div class="stat-value">${bytes(s.usage||0)}</div><p class="micro">浏览器提供的当前站点使用量 / 可用配额 ${s.quota?bytes(s.quota):'未提供'}</p><div class="storage-meter"><div style="width:${s.quota?Math.min(100,(s.usage||0)/s.quota*100):0}%"></div></div><p class="micro">持久存储：${s.persisted?'已获准':'尚未获准'}</p>`;}catch(e){$('#storage-status').textContent='当前浏览器未提供容量信息。项目仍使用 IndexedDB 保存。';}}
async function bindVideo(){const video=$('#review-video'),p=state.project;const epoch=navigationEpoch;if(!video||!p?.video||p.video.needsReattach)return;try{let src;if(synthetic(p))src=p.video.url;else{const blob=await store.getMedia(p.video.id);if(epoch!==navigationEpoch||!video.isConnected||state.project?.id!==p.id)return;if(!blob){$('#video-empty').hidden=false;$('#video-empty strong').textContent='本机视频缺失，请重新绑定';return;}state.objectURL=URL.createObjectURL(blob);src=state.objectURL;}video.dataset.mediaId=p.video.id;video.src=src;video.addEventListener('loadedmetadata',()=>{if(!video.isConnected||state.project?.id!==p.id)return;if(Math.abs(video.duration-p.video.duration)>.15){$('#video-empty').hidden=false;$('#video-empty strong').textContent='视频时长与保存记录不一致';video.pause();return;}$('#video-empty').hidden=true;if(state.route==='review'&&selectedPlay())video.currentTime=selectedPlay().start;});video.addEventListener('timeupdate',()=>{if(!video.isConnected||state.project?.id!==p.id)return;const t=video.currentTime;if($('#video-time'))$('#video-time').textContent=`${time(t)} / ${time(video.duration)}`;const play=p.plays.find(v=>v.start<=t&&t<v.end),cap=$('#video-caption');if(cap){cap.hidden=!play||state.recording;cap.textContent=play?`${play.shooter} · ${play.points} 分出手 · ${t>=play.resultTime?result(play):'结果待揭示'}`:'';}if(state.preview){const clip=p.playlist[state.preview.index];if(clip&&t>=clip.out-.04){const next=p.playlist[++state.preview.index];if(next){video.currentTime=next.in;video.play().catch(fail);}else{video.pause();state.preview=null;toast('片单预览完成');}}}});video.addEventListener('error',()=>{if(!video.isConnected||state.project?.id!==p.id)return;$('#video-empty').hidden=false;$('#video-empty strong').textContent='当前浏览器无法解码这个视频';toast('请使用兼容的 MP4/H.264 或 WebM 文件，或在完整本机版中处理。');});}catch(e){fail(e);}}
function showDialog(title,body){$('#dialog-content').innerHTML=`<div class="dialog-head"><h2>${esc(title)}</h2>${button('×','close-dialog','text-button','aria-label="关闭窗口"')}</div><div class="dialog-body">${body}</div>`;if(!$('#dialog').open)$('#dialog').showModal();}
function closeDialog(){$('#dialog').close();state.importing=null;}
function newProject(scenario='coach'){showDialog('创建比赛项目',`<form id="new-form"><div class="form-grid"><label class="field full"><span>项目名称</span><input name="name" required maxlength="160" placeholder="例如：校队 vs 理工 · 赛后复盘" autofocus></label>${field('比赛日期','date',new Date().toLocaleDateString('en-CA'),'date')}${field('对手 / 比赛双方','opponent','','text','maxlength="160"')}<label class="field full"><span>素材来源</span><input name="source" placeholder="例如：球队自摄比赛视频，已取得使用许可" maxlength="2000"></label><div class="field full"><span>主要工作场景</span><div class="scenario-picker">${[['coach','教练赛后复盘','逐回合复核、球员比较、训练报告'],['editor','赛事内容制作','筛片、调整片段、生成短片']].map(([v,t,d])=>`<label class="scenario"><input type="radio" name="scenario" value="${v}" ${scenario===v?'checked':''}><div><strong>${t}</strong><small>${d}</small></div></label>`).join('')}</div></div></div><div class="form-actions"><button type="button" data-action="close-dialog">取消</button><button type="submit" class="primary">创建并进入工作区</button></div></form>`);}
async function saveProject(draft,description,{renderNow=true}={}){draft=structuredClone(draft);if(description)draft.activity=[...(draft.activity||[]),{at:new Date().toISOString(),type:'edit',message:description}].slice(-1000);try{const saved=await store.save(draft,draft.revision);state.project=saved;state.dirty=false;await loadProjects();if(renderNow)await render();return saved;}catch(e){if(e.code==='CONFLICT'){state.conflictedDraft=draft;showDialog('保存发生版本冲突',`<p>另一个页面已经更新了这个项目。当前修改没有覆盖最新数据。你可以先下载草稿，再载入最新版本进行比对。</p><div class="actions">${button('下载我的草稿','conflict-backup','primary')}${button('载入最新版本','reload-project')}</div>`);}throw e;}}
function readPlayForm(){const f=$('#play-form');if(!f)return selectedPlay();if(!f.reportValidity())throw new Error('请完整填写回合表单。');const data=new FormData(f),old=selectedPlay(),v={...old};for(const k of ['start','end','shotTime','resultTime','points'])v[k]=Number(data.get(k));for(const k of ['xfg','x','y'])v[k]=String(data.get(k)).trim()===''?null:Number(data.get(k));for(const k of ['shooter','team','tag','notes','source'])v[k]=String(data.get(k)).trim();v.made=data.get('made')==='unknown'?null:data.get('made')==='made';return v;}
async function savePlay(review=false){const draft=structuredClone(state.project),v=readPlayForm(),idx=draft.plays.findIndex(p=>p.id===v.id);draft.plays[idx]=v;draft.status='draft';const errors=validateProject(draft).filter(i=>i.severity==='error');if(errors.length)throw new Error('回合内容不能保存：'+errors.map(issueText).join('；'));await saveProject(draft,'保存回合 '+v.shooter,{renderNow:false});if(review){const approved=structuredClone(state.project),a=approved.plays.find(p=>p.id===v.id);a.reviewed=!selectedPlay().reviewed;await saveProject(approved,a.reviewed?'复核回合 '+a.shooter:'撤销回合复核 '+a.shooter);}else await render();toast(review?(selectedPlay().reviewed?'已确认本条回合；记录已保存':'已撤销复核'):'修改已保存；每次保存都可从历史中恢复');}
async function addPlay(){const p=structuredClone(state.project),duration=p.video?.duration||3600,start=Math.min($('#review-video')?.currentTime||0,Math.max(0,duration-1)),end=Math.min(duration,start+8);const v={id:id('play'),start:+start.toFixed(2),end:+end.toFixed(2),shotTime:+Math.min(end,start+2).toFixed(2),resultTime:+Math.min(end,start+3).toFixed(2),shooter:'待填写球员',team:'',points:2,made:null,tag:'',notes:'',reviewed:false,xfg:null,x:null,y:null,source:p.source};p.plays.push(v);p.status='draft';state.selected=v.id;await saveProject(p,'添加回合');toast('已添加回合，请对照视频填写球员和实际时刻');}
async function addClips(ids){const p=structuredClone(state.project);const added=p.plays.filter(v=>ids.includes(v.id));p.playlist.push(...added.map(v=>({id:id('clip'),playId:v.id,in:v.start,out:v.end,title:`${v.shooter} · ${v.tag||'比赛回合'}`})));p.status='draft';await saveProject(p,`加入 ${added.length} 个片段`);toast(`已加入 ${added.length} 个片段，前往「片单制作」调整顺序`);}
async function selectPlay(playId){if(state.dirty){showDialog('当前回合有未保存修改',`<p>保存当前修改后再切换回合，或放弃本次未保存内容。</p><div class="actions">${button('保存后切换','save-switch','primary',`data-id="${esc(playId)}"`)}${button('放弃并切换','discard-switch','',`data-id="${esc(playId)}"`)}</div>`);return;}state.selected=playId;await render();}
function importDialog(){if(!state.project)return;showDialog('导入回合数据',`<p>支持 CSV 与 JSON，最多 2,000 条回合。时间统一为视频秒数，未知结果和缺失指标可以留空。</p><div class="form-grid"><label class="field full"><span>本次数据来源</span><input id="import-source" value="${esc(state.project.source)}" placeholder="填写数据来源与记录方式"></label><label class="field full"><span>导入方式</span><select id="import-mode"><option value="append">追加到当前回合库</option><option value="replace">替换当前回合库，并清空片单（历史保留）</option></select></label></div><div class="actions section-space">${button('选择 CSV / JSON','choose-data','primary')}${button('下载 CSV 模板','template')}</div><div id="import-preview" class="section-space"></div>`);}
async function inspectData(file){if(!file)return;const source=$('#import-source')?.value||'',mode=$('#import-mode')?.value||'append';if(file.size>8*1024*1024)throw new Error('回合表不能超过 8 MB。');const parsed=parseImport(await file.text(),{format:file.name.toLowerCase().endsWith('.csv')?'csv':'json',duration:state.project.video?.duration||null,source});if(mode==='append'&&parsed.plays.some(v=>state.project.plays.some(p=>p.id===v.id)))throw new Error('导入回合 ID 与现有数据重复。请选择替换，或调整 ID 后重试。');state.importing={...parsed,mode,file:file.name};$('#import-preview').innerHTML=`<div class="info"><b>${esc(file.name)}</b> · ${parsed.plays.length} 条回合 · ${parsed.issues.length} 条提示<br>导入不会自动标记为已复核。</div>${parsed.issues.length?`<ul class="issues">${parsed.issues.slice(0,5).map(i=>`<li>${esc(issueText(i))}</li>`).join('')}</ul>`:''}<div class="form-actions">${button(mode==='replace'?'确认替换并保留历史':'确认导入','commit-import','primary')}</div>`;}
async function attachVideo(file){if(!file)return;const targetProject=structuredClone(state.project);if(file.size>512*1024*1024)throw new Error('单个视频最多 512 MB，较大素材请使用完整本机版。');if(!file.size)throw new Error('不能导入空视频。');toast('正在检查视频并保存到本机…');const url=URL.createObjectURL(file),v=document.createElement('video');let metadata;try{metadata=await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(new Error('读取视频信息超时，请使用浏览器兼容的视频格式。')),15000);v.onloadedmetadata=()=>{clearTimeout(timer);resolve({duration:v.duration,width:v.videoWidth,height:v.videoHeight});};v.onerror=()=>{clearTimeout(timer);reject(new Error('当前浏览器无法解码视频，请尝试 MP4/H.264 或 WebM。'));};v.preload='metadata';v.src=url;});}finally{v.removeAttribute('src');v.load();URL.revokeObjectURL(url);}if(!Number.isFinite(metadata.duration)||!metadata.width)throw new Error('无法读取有效的视频时长和尺寸。');const p=targetProject,mediaId=id('media');p.video={id:mediaId,name:file.name,size:file.size,...metadata,sha256:''};p.status='draft';p.plays.forEach(v=>v.reviewed=false);const errors=validateProject(p).filter(i=>i.severity==='error');if(errors.length)throw new Error('视频与回合时间不匹配：'+errors.map(issueText).join('；'));const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());p.video.sha256=Array.from(new Uint8Array(digest),b=>b.toString(16).padStart(2,'0')).join('');await store.putMedia(mediaId,file);await saveProject(p,'绑定视频 '+file.name);toast('视频已保存在本机；回合需要重新复核');}
async function approve(){const p=structuredClone(state.project);p.status='approved';const errors=validateProject(p).filter(i=>i.severity==='error');if(errors.length){showDialog('还有项目尚未完成',`<ul class="issues">${errors.map(i=>`<li class="error">${esc(issueText(i))}</li>`).join('')}</ul><div class="form-actions">${button('回到回合复核','review','primary')}</div>`);return;}await saveProject(p,'批准当前项目');toast('当前项目已批准，可以录制片单成片');}
async function record(){if(state.recording)return;const p=structuredClone(state.project),video=$('#review-video');if(!video?.src)throw new Error('请先绑定可播放的视频。');state.recording=true;video.controls=false;state.abort=new AbortController();$('#record-progress').hidden=false;document.querySelectorAll('button:not([data-action="cancel-record"]),select,input,textarea').forEach(e=>e.disabled=true);const route=location.hash;try{const output=await recordPlaylist({project:p,video,signal:state.abort.signal,onProgress:info=>{if($('#record-bar'))$('#record-bar').style.width=`${Math.round(info.progress*100)}%`;if($('#record-stage'))$('#record-stage').textContent=`${info.stage} · ${Math.round(info.progress*100)}%`;}});download(output.blob,filename(p)+'-r'+p.revision+'.'+(output.mimeType.includes('mp4')?'mp4':'webm'),output.mimeType);const update=structuredClone(state.project);await saveProject(update,`完成成片录制 · r${p.revision} · ${time(output.duration)}`,{renderNow:false});toast('真实视频已生成并下载；成片为无声视频');}catch(e){if(e.name==='AbortError')toast('录制已取消，没有生成交付文件');else fail(e);}finally{state.recording=false;video.controls=true;state.abort=null;location.hash=route;await render();}}
function projectInfo(){const p=state.project;showDialog('项目资料与来源',`<form id="info-form"><div class="form-grid"><label class="field full"><span>项目名称</span><input name="name" value="${esc(p.name)}" maxlength="160" required></label>${field('比赛日期','date',p.date,'date')}${field('对手 / 比赛双方','opponent',p.opponent)}<label class="field full"><span>素材与数据来源</span><textarea name="source" maxlength="2000">${esc(p.source)}</textarea></label></div><div class="form-actions">${button(p.archived?'恢复归档项目':'归档项目','archive','text-button','type="button"')}<button type="submit" class="primary">保存资料</button></div></form>`);}
async function history(){const rows=await store.history(state.project.id);state.history=rows;showDialog('项目版本历史',`<p>每次保存都会形成新版本。恢复旧版会创建新的修订，不删除现有历史；恢复后的项目需要重新复核。</p>${rows.map(r=>`<div class="history-row"><div><strong>r${r.revision} · ${esc(r.name||r.project?.name)}</strong><small>${date(r.at)} · ${r.project?.plays.length??0} 条回合 / ${r.project?.playlist.length??0} 个片段</small></div>${button(r.revision===state.project.revision?'当前':'恢复此版本','restore','small',`data-revision="${r.revision}" ${r.revision===state.project.revision?'disabled':''}`)}</div>`).join('')}`);}
async function runAction(action,el){const p=state.project;switch(action){case'new':case'new-coach':newProject('coach');break;case'new-editor':newProject('editor');break;case'close-dialog':closeDialog();break;case'demo':{toast('正在载入合成演练…');const r=await fetch('data/demo.json');if(!r.ok)throw new Error('无法载入演练数据。');const data=demoProject(await r.json());data.name='HOU vs DAL · 合成复盘演练';state.project=await store.save(data,0);await loadProjects();goto('review');break;}case'projects':goto('projects');break;case'review':closeDialog();goto('review');break;case'reports':goto('reports');break;case'project-info':projectInfo();break;case'attach-video':$('#video-file').click();break;case'import-data':importDialog();break;case'choose-data':$('#data-file').click();break;case'import-backup':$('#backup-file').click();break;case'commit-import':{const d=structuredClone(p),im=state.importing;if(!im)break;d.plays=im.mode==='replace'?im.plays:[...d.plays,...im.plays];if(im.mode==='replace')d.playlist=[];d.status='draft';await saveProject(d,`导入 ${im.plays.length} 条回合`);closeDialog();toast('回合已导入并保存，请逐条复核');break;}case'add-play':await addPlay();break;case'select-play':await selectPlay(el.dataset.id);break;case'review-id':state.selected=el.dataset.id;goto('review');break;case'save-switch':await savePlay();state.selected=el.dataset.id;closeDialog();await render();break;case'discard-switch':state.dirty=false;state.selected=el.dataset.id;closeDialog();await render();break;case'review-play':await savePlay(true);break;case'delete-play':showDialog('删除当前回合',`<p>删除「${esc(selectedPlay().shooter)}」的当前回合，也会移除引用它的片段。之前版本仍可从历史中恢复。</p><div class="actions">${button('取消','close-dialog')}${button('删除并保存新版本','confirm-delete-play','danger')}</div>`);break;case'confirm-delete-play':{const d=structuredClone(p);d.plays=d.plays.filter(v=>v.id!==state.selected);d.playlist=d.playlist.filter(v=>v.playId!==state.selected);d.status='draft';state.selected=null;await saveProject(d,'删除回合（历史保留）');closeDialog();break;}case'add-clip':if(state.dirty)await savePlay();await addClips([state.selected]);break;case'clip-id':await addClips([el.dataset.id]);break;case'add-filtered':await addClips(filteredPlays(p).map(v=>v.id));break;case'add-all':await addClips(p.plays.map(v=>v.id));break;case'clip-up':case'clip-down':case'clip-remove':{if(state.dirty)throw new Error('请先保存片单修改，再调整顺序或移除片段。');const d=structuredClone(p),i=d.playlist.findIndex(c=>c.id===el.dataset.id),offset=action==='clip-up'?-1:1;if(action==='clip-remove')d.playlist.splice(i,1);else if(i+offset>=0&&i+offset<d.playlist.length)[d.playlist[i],d.playlist[i+offset]]=[d.playlist[i+offset],d.playlist[i]];d.status='draft';await saveProject(d,'调整片单');break;}case'preview-playlist':{if(state.dirty)throw new Error('请先保存片单再预览。');const v=$('#review-video');if(!v.src)throw new Error('请先绑定视频。');state.preview={index:0};v.currentTime=p.playlist[0].in;await v.play();break;}case'back':case'forward':{const v=$('#review-video');if(Number.isFinite(v?.duration))v.currentTime=Math.max(0,Math.min(v.duration,v.currentTime+(action==='back'?-3:3)));break;}case'quality':showDialog('完整数据检查',issuesHTML(p,100));break;case'approve':await approve();break;case'backup':download(JSON.stringify(projectBackup(p)),filename(p)+'-r'+p.revision+'.json');toast('项目备份已下载；请另外保留原视频');break;case'conflict-backup':download(JSON.stringify(projectBackup(state.conflictedDraft)),filename(p)+'-未提交草稿.json');break;case'reload-project':closeDialog();state.project=await store.get(p.id);state.dirty=false;await loadProjects();await render();break;case'csv':case'filtered-csv':download(toCSV(action==='csv'?p.plays:filteredPlays(p)),filename(p)+'-回合表.csv','text/csv;charset=utf-8');break;case'report':download(makeReport(p),filename(p)+'-r'+p.revision+'-复盘报告.html','text/html;charset=utf-8');toast('复盘报告已下载，打开后可打印为 PDF');break;case'vtt':download(makeVTT(p),filename(p)+'-片单字幕.vtt','text/vtt;charset=utf-8');break;case'record':await record();break;case'cancel-record':state.abort?.abort();break;case'history':await history();break;case'restore':{state.project=await store.restore(p.id,Number(el.dataset.revision),p.revision);await loadProjects();closeDialog();state.selected=null;await render();toast('已恢复为新版本，原历史保留；请重新复核');break;}case'archive':if(p.archived){const d=structuredClone(p);d.archived=false;d.status='draft';await saveProject(d,'恢复归档项目');}else{state.project=await store.archive(p.id,p.revision);await loadProjects();}closeDialog();goto('projects');break;case'persist':{const ok=await store.requestPersistence();await storageStatus();toast(ok?'浏览器已允许持久存储；仍建议定期备份':'浏览器没有授予持久存储，请保留项目备份和原视频');break;}case'template':download('id,start,end,shotTime,resultTime,shooter,team,points,made,tag,notes,xfg,x,y,source\nplay-01,0,8,5,6,球员姓名,球队名称,2,unknown,待填写,请用真实记录替换示例行,,,,人工记录\n','CourtLens-回合导入模板.csv','text/csv;charset=utf-8');break;}}
function setBusy(value){state.busy=value;document.querySelectorAll('#play-form,#playlist-form').forEach(e=>e.inert=value);}
function fail(e){state.navigating=false;$('#main').inert=false;console.error('CourtLens Studio',e);toast(message(e));}
async function submit(form){const d=new FormData(form);if(form.id==='new-form'){const p=createProject(Object.fromEntries(d));state.project=await store.save(p,0);await loadProjects();closeDialog();goto('review');toast('项目已创建；现在可以导入视频和回合数据');}else if(form.id==='play-form')await savePlay();else if(form.id==='info-form'){const p=structuredClone(state.project);for(const k of ['name','date','opponent','source'])p[k]=String(d.get(k)).trim();p.status='draft';await saveProject(p,'修改项目资料');closeDialog();}else if(form.id==='playlist-form'){const p=structuredClone(state.project);for(const c of p.playlist){c.in=Number(d.get('in-'+c.id));c.out=Number(d.get('out-'+c.id));c.title=String(d.get('title-'+c.id)).trim();}p.status='draft';await saveProject(p,'保存片单入出点与标题');toast('片单已保存；导出前请批准当前项目');}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;e.preventDefault();if((state.busy||state.navigating)&&el.dataset.action!=='cancel-record')return;if(state.dirty&&!['close-dialog','review-play','add-clip','select-play','save-switch','discard-switch','back','forward','conflict-backup'].includes(el.dataset.action)){toast('当前表单有未保存修改，请先保存再进行其他操作。');return;}setBusy(true);runAction(el.dataset.action,el).catch(fail).finally(()=>setBusy(false));});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#/"]');if(a&&(state.recording||state.busy)){e.preventDefault();toast(state.recording?'请先完成或取消录制。':'当前操作正在保存，请稍后切换页面。');}else if(a&&state.dirty){e.preventDefault();showDialog('修改尚未保存',`<p>请先保存表单，再切换工作页面。当前草稿仍保留在表单里。</p>${button('继续编辑','close-dialog','primary')}`);}else if(a?.dataset.play)state.selected=a.dataset.play;});
document.addEventListener('submit',e=>{e.preventDefault();if(state.busy||state.navigating)return;setBusy(true);submit(e.target).catch(fail).finally(()=>setBusy(false));});
document.addEventListener('input',e=>{if(e.target.closest('#play-form,#playlist-form'))state.dirty=true;});
document.addEventListener('change',e=>{const map={'review-filter':'review','player-filter':'player','tag-filter':'tag','result-filter':'result','project-status':'review','project-search':'search'};if(map[e.target.id]){if(state.dirty||state.busy){toast('请先保存表单修改，再切换筛选。');return;}state.filter[map[e.target.id]]=e.target.value;render().catch(fail);}if(e.target.id==='active-project'){if(state.dirty||state.recording||state.busy||state.navigating){toast('请先保存修改或等待当前操作完成。');refreshShell();return;}if(e.target.value){goto('review',{id:e.target.value});}}});
$('#video-file').addEventListener('change',e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(state.busy||state.navigating)return;setBusy(true);attachVideo(file).catch(fail).finally(()=>setBusy(false));});
$('#data-file').addEventListener('change',e=>{const file=e.target.files[0];e.target.value='';inspectData(file).catch(error=>{const target=$('#import-preview');if(target)target.innerHTML=`<div class="error-box">导入失败：${esc(message(error))}</div>`;fail(error);});});
$('#backup-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file||state.busy||state.navigating)return;setBusy(true);try{if(file.size>64*1024*1024)throw new Error('备份 JSON 不能超过 64 MB。');const p=readBackup(await file.text());state.project=await store.save(p,0);await loadProjects();goto('review');toast('备份已作为新项目导入；请重新绑定视频并复核');}catch(error){fail(error);}finally{setBusy(false);}});
window.addEventListener('hashchange',()=>{if(state.dirty||state.recording||state.busy||state.navigating){window.history.replaceState(null,'',acceptedHash);toast(state.dirty?'请先保存表单；未保存内容已保留。':'请等待当前操作完成后再切换页面。');return;}navigate().catch(fail);});window.addEventListener('beforeunload',e=>{if(state.dirty||state.recording){e.preventDefault();e.returnValue='';}});
async function init(){try{if(location.pathname.startsWith('/studio/'))document.querySelector('.sidebar-bottom a').href='/';await store.open();await loadProjects();await navigate();}catch(e){$('#main').innerHTML=empty('无法打开本机工作室','浏览器存储未能初始化。请使用允许网站存储的普通浏览模式，或下载完整本机版。',`<a href="demo.html">打开无需保存的证据演示 →</a>`)+`<p class="error-box section-space">${esc(message(e))}</p>`;console.error(e);}}
init();
